bodyParameters.body:
${({
  contents: [{
    parts: [
      {
        text: "You are an expert technical recruiter. Analyze the attached resume PDF and generate a clean summary with: 1) Full Name, 2) Total Years of Experience, 3) Top 5 Technical Skills, 4) 3-sentence Executive Summary, and 5) Key Interview Focus Areas."
      },
      {
        inlineData: {
          mimeType: "application/pdf",
          data: $context.outputs.File_to_Base64_1.output.serializeData()
        }
      }
    ]
  }]
})
}
